console.log(`▶ Montar resumo da checagem  integração=${$json.integracaoOk}  furos=${($json.notasAusentes || []).length}`);
function parseFakeNota(raw) {
  const v = String(raw ?? '').trim();
  if (!v || /^(0|false|off|no|desligada|disabled)$/i.test(v)) return null;
  const m = v.match(/^(\d+)\s*[\/,;x-]\s*(\d+)$/i);
  if (!m) return null;
  return { numero: Number(m[1]), serie: Number(m[2]) };
}

function horarioSaoPaulo() {
  return new Intl.DateTimeFormat('pt-BR', {
    timeZone: 'America/Sao_Paulo',
    day: '2-digit',
    month: '2-digit',
    year: 'numeric',
    hour: '2-digit',
    minute: '2-digit',
    hour12: false,
  }).format(new Date());
}

function listarAusentes(notas) {
  const porSerie = new Map();
  for (const n of notas) {
    const s = Number(n.serie);
    if (!porSerie.has(s)) porSerie.set(s, []);
    porSerie.get(s).push(Number(n.numero));
  }
  const linhas = [];
  for (const [serie, nums] of [...porSerie.entries()].sort((a, b) => a[0] - b[0])) {
    nums.sort((a, b) => a - b);
    const partes = [];
    let i = 0;
    while (i < nums.length) {
      let j = i;
      while (j + 1 < nums.length && nums[j + 1] === nums[j] + 1) j++;
      partes.push(i === j ? String(nums[i]) : `${nums[i]}–${nums[j]}`);
      i = j + 1;
    }
    linhas.push(`série ${serie}: ${partes.join(', ')}`);
  }
  return linhas.join('\n');
}

const sftp = $input.first().json;
const executionId = $execution.id;
const horario = horarioSaoPaulo();

if (sftp.ok === false || sftp.erro) {
  throw new Error(`Checar SFTP falhou: ${sftp.erro || 'resposta inválida'}`);
}

const series = Array.isArray(sftp.series) ? sftp.series : [];
let notasAusentes = Array.isArray(sftp.notasAusentes) ? [...sftp.notasAusentes] : [];
let integracaoOk = series.length > 0 && series.every((s) => s.totalAusentes === 0);

const fake = parseFakeNota($env.FAKE_NOTA);
if (fake) {
  if (!notasAusentes.some((n) => n.numero === fake.numero && n.serie === fake.serie)) {
    notasAusentes = [fake, ...notasAusentes];
  }
  integracaoOk = false;
}

const identificador = sftp.identificador || '';
const periodo = sftp.tetoPeriodo
  ? (sftp.tetoPeriodo.start === sftp.tetoPeriodo.end
      ? `Período teto ML: ${sftp.tetoPeriodo.start}`
      : `Período teto ML: ${sftp.tetoPeriodo.start}–${sftp.tetoPeriodo.end}`)
  : '';
const seriesLinha = series
  .map((s) => {
    const teto = s.tetoMl != null ? `, teto ML ${s.tetoMl} ` : '';
    return `série ${s.serie} (FTP ${s.min} → ${s.max}${teto})`;
  })
  .join('\n');

const cabecalho = [identificador, periodo, seriesLinha].filter(Boolean).join('\n');
const prefixoTeste = fake ? `[TESTE FAKE_NOTA] ` : '';

const mensagemOk =
  `${prefixoTeste}Monitoramento concluído ${horario}\n\n` +
  'A integração de NF-e das séries monitoradas está 100% OK.\n' +
  'A última NF emitida pelo Mercado Livre está no FTP.\n\n' +
  cabecalho;

const listaNotas = notasAusentes.length ? listarAusentes(notasAusentes) : '';
const mensagemErro =
  `${prefixoTeste}Monitoramento com pendências ${horario}\n\n` +
  cabecalho +
  (listaNotas
    ? `\n\nNotas ausentes no FTP (${notasAusentes.length}):\n${listaNotas}\n\nDiagnóstico automático em todas.`
    : '');

try {
  $execution.customData.set('executionId', String(executionId));
  $execution.customData.set('integracaoOk', String(integracaoOk));
  $execution.customData.set('furos', String(notasAusentes.length));
} catch (e) {}

return [
  {
    json: {
      identificador,
      series,
      tetoPeriodo: sftp.tetoPeriodo || null,
      integracaoOk,
      notasAusentes,
      fakeNota: fake,
      executionId,
      assunto: prefixoTeste + (integracaoOk
        ? `Monitoramento concluído ${horario}`
        : `Monitoramento com pendências ${horario}`),
      mensagem: integracaoOk ? mensagemOk : mensagemErro,
    },
  },
];

const run = $getWorkflowStaticData('run');
run.lote = [];
console.log(`▶ Separar NFs ausentes  furos=${($('Montar resumo da checagem').first().json.notasAusentes || []).length}`);
const seller = $input.first().json;
const avaliacao = $('Montar resumo da checagem').first().json;
const mlUserId = seller.id || $env.ML_USER_ID;
const executionId = avaliacao.executionId || $execution.id;

if (!mlUserId) {
  throw new Error('GET /users/me não retornou id. Token inválido ou expirado.');
}

const notas = Array.isArray(avaliacao.notasAusentes) ? avaliacao.notasAusentes : [];
if (notas.length === 0) {
  return [{
    json: {
      motivo: 'serie_sem_xml_ou_sem_furo_listavel',
      mlUserId,
      identificador: avaliacao.identificador,
      executionId,
      furosTotais: 0,
      furosProcessados: 0,
    },
  }];
}

return notas.map((n) => ({
  json: {
    numero: n.numero,
    serie: n.serie,
    referencia: `${n.numero}/${n.serie}`,
    motivo: 'xml_ausente_ftp',
    mlUserId,
    identificador: avaliacao.identificador,
    executionId,
    furosTotais: notas.length,
    furosProcessados: notas.length,
  },
}));

console.log(`▶ Normalizar invoice  ${$json.referencia}  encontrado=${$json.encontrado}`);
const origem = $('Separar NFs ausentes').item.json;
const rel = $input.first().json;
const falhou = Boolean(rel.error || rel.erro || rel.ok === false);
const invoiceId = falhou ? null : (rel.invoiceId ?? null);

return [{
  json: {
    referencia: origem.referencia,
    numero: origem.numero,
    serie: origem.serie,
    invoiceId,
    chave: falhou ? null : (rel.chave ?? null),
    xmlNome: rel.xmlNome ?? null,
    periodo: rel.periodo ?? null,
    tentativas: rel.tentativas ?? null,
    encontrado: Boolean(!falhou && rel.encontrado && invoiceId),
    motivo: falhou
      ? (rel.erro || rel.error?.message || 'falha_http_buscar_invoice')
      : (rel.encontrado && invoiceId
        ? 'xml_ausente_ftp'
        : (rel.erro || 'invoice_nao_encontrada_no_relatorio_ml')),
    identificador: origem.identificador,
    executionId: origem.executionId,
    mlUserId: origem.mlUserId,
  },
}];

console.log(`▶ Série sem XML para cruzar  ${$json.identificador || ''}`);
const origem = $input.first().json;
const executionId = origem.executionId || $execution.id;
const quem = origem.referencia || origem.identificador || '';
const mensagem =
  (quem ? `NF ${quem}\n\n` : '') +
  '⚠️ Precisa de atenção — não foi possível cruzar esta série com o Mercado Livre.\n' +
  'Não há XML no FTP para montar a sequência das notas.\n\n' +
  'O que fazer:\n' +
  'Acionar o time técnico.\n\n' +
  `execução n8n=${executionId}`;

return [{
  json: {
    encontrado: false,
    precisaAdmin: true,
    proximaAcao: 'nenhuma',
    motivo: origem.motivo || 'serie_sem_xml_ou_sem_furo_listavel',
    identificador: origem.identificador,
    mlUserId: origem.mlUserId,
    executionId,
    assunto: `NF-e ${origem.identificador || ''} — série sem XML para cruzar`,
    mensagem,
  },
}];

console.log(`▶ Montar relatório do furo  ${$json.referencia || ''}  ${$json.proximaAcao || ''}`);
function jsonDe(nomeNo) {
  try {
    return $(nomeNo).item.json;
  } catch (e) {
    return null;
  }
}

const entrada = $input.first().json;
const executionId = entrada.executionId || $execution.id;
const diag = jsonDe('Diagnosticar no Nerus');
const sftp = jsonDe('Rechecar FTP');
const entrega = jsonDe('Rechecar entrega no Nerus');
const origem = jsonDe('Normalizar invoice') || entrada;

if (!diag && entrada.mensagem) {
  const jaTemExec = String(entrada.mensagem).includes('execução n8n=');
  return [{
    json: {
      ...entrada,
      executionId,
      mensagem: jaTemExec ? entrada.mensagem : `${entrada.mensagem}\n\nexecução n8n=${executionId}`,
    },
  }];
}

let xmlNoFtp = null;
if (sftp && Array.isArray(sftp.notasAusentes)) {
  const aindaFuro = sftp.notasAusentes.some(
    (n) => Number(n.numero) === Number(origem.numero) && Number(n.serie) === Number(origem.serie),
  );
  xmlNoFtp = !aindaFuro;
}

const classificacaoEntrega = (entrega && entrega.classificacaoEntrega) || null;
const referencia = origem.referencia || (diag && diag.referencia) || '';
const invoiceId = origem.invoiceId || (diag && diag.invoiceId) || '';
const chave = (diag && diag.chave) || origem.chave || '';
const diagnostico = (diag && diag.diagnostico) || '';
const proximaAcao = (diag && diag.proximaAcao) || origem.proximaAcao || 'nenhuma';
const passos = diag && Array.isArray(diag.passos) ? diag.passos : [];
const contigencia = diag && diag.contigencia;

function oQueMonitorFez() {
  const c = passos.find((p) => p.id === 'contigencia');
  if (c && c.status === 'ok') {
    if (xmlNoFtp === true) return 'Reenviou o aviso ao sistema (contingência). Depois disso, o XML apareceu no FTP.';
    if (xmlNoFtp === false) return 'Reenviou o aviso ao sistema (contingência) e conferiu de novo. A nota ainda não chegou ao FTP.';
    return 'Reenviou o aviso ao sistema (contingência).';
  }
  if (c && c.status === 'erro') {
    return `Tentou reenviar o aviso ao sistema (contingência), mas não conseguiu: ${c.detalhe}`;
  }
  if (proximaAcao === 'esperar_entrega') {
    if (xmlNoFtp === true) return 'Aguardou o envio ao FTP. O XML apareceu na pasta.';
    if (xmlNoFtp === false) return 'Aguardou o envio ao FTP, mas o arquivo ainda não apareceu na pasta.';
    return 'A nota já estava no Nerus; o envio ao FTP ainda estava em andamento.';
  }
  if (proximaAcao === 'rechecar_ftp') {
    if (xmlNoFtp === true) return 'Conferiu o FTP e encontrou o XML.';
    if (xmlNoFtp === false) return 'O envio ao FTP já tinha sido disparado, mas o arquivo ainda não estava na pasta.';
    return 'O envio ao FTP já tinha sido disparado. Falta conferir se o XML chegou na pasta.';
  }
  return 'Não reenviou o aviso: o problema não é falta de notificação do Mercado Livre.';
}

let banner;
let oQueFazer;
let assuntoSufixo;
let resolvido;
let precisaAdmin;
if (xmlNoFtp === true) {
  banner = '✅ Resolvido — o XML da nota já está no FTP.';
  oQueFazer = 'Nada a fazer.';
  assuntoSufixo = 'resolvido';
  resolvido = true;
  precisaAdmin = false;
} else if (xmlNoFtp === false && classificacaoEntrega === 'enviada') {
  banner = '⏳ Em andamento — o envio ao FTP já foi disparado, mas o arquivo ainda não apareceu na pasta.';
  oQueFazer = 'Aguardar o próximo ciclo de monitoramento. Se a nota não aparecer, acionar o time técnico.';
  assuntoSufixo = 'envio em andamento';
  resolvido = false;
  precisaAdmin = true;
} else if (xmlNoFtp === false) {
  banner = '⚠️ Ainda não resolvido — a nota continua ausente no FTP.';
  oQueFazer = 'Acionar o time técnico.';
  assuntoSufixo = 'ainda ausente no FTP';
  resolvido = false;
  precisaAdmin = true;
} else if (proximaAcao === 'contigencia') {
  banner = '⚠️ Pendência — o Mercado Livre não avisou o sistema.';
  oQueFazer = 'O monitor já reenviou o aviso. Aguardar 1–3 minutos e conferir se o XML chegou ao FTP.';
  assuntoSufixo = 'Mercado Livre não avisou';
  resolvido = false;
  precisaAdmin = true;
} else if (proximaAcao === 'esperar_entrega') {
  banner = '⏳ Em andamento — a nota está no Nerus, aguardando o envio ao FTP.';
  oQueFazer = 'Aguardar cerca de 10 minutos e conferir de novo.';
  assuntoSufixo = 'aguardando envio ao FTP';
  resolvido = false;
  precisaAdmin = true;
} else if (proximaAcao === 'rechecar_ftp') {
  banner = '⏳ Em andamento — conferindo se o XML já está no FTP.';
  oQueFazer = 'Conferir o FTP. Se o XML não estiver lá, acionar o time técnico.';
  assuntoSufixo = 'conferir FTP';
  resolvido = false;
  precisaAdmin = false;
} else {
  banner = '⚠️ Precisa de atenção — a nota não chegou ao FTP.';
  oQueFazer = 'Acionar o time técnico. Este caso não se resolve sozinho.';
  assuntoSufixo = 'precisa de atenção';
  resolvido = false;
  precisaAdmin = true;
}

if (sftp && (sftp.error || sftp.ok === false)) {
  oQueFazer = `Não deu para conferir o FTP (${sftp.erro || (sftp.error && sftp.error.message) || 'HTTP'}). ${oQueFazer}`;
}

const linhas = [
  `NF ${referencia}`,
  '',
  banner,
  oQueFazer,
  '',
  xmlNoFtp === true ? 'O que tinha acontecido:' : 'O que aconteceu:',
  diagnostico || 'Não foi possível montar o diagnóstico.',
  '',
  'O que o monitor fez:',
  oQueMonitorFez(),
];

if (xmlNoFtp !== true) {
  const pipeline = passos.filter((p) => p.id !== 'contigencia');
  const primeiroErro = pipeline.findIndex((p) => p.status === 'erro');
  const visiveis = primeiroErro >= 0 ? pipeline.slice(0, primeiroErro + 1) : pipeline;
  if (visiveis.length) {
    linhas.push('', 'Onde a integração parou:');
    for (const p of visiveis) {
      linhas.push(p.detalhe ? `• ${p.titulo} — ${p.detalhe}` : `• ${p.titulo}`);
    }
    if (primeiroErro >= 0 && primeiroErro < pipeline.length - 1) {
      linhas.push('Os passos seguintes ainda não rodaram por causa disso.');
    }
  }
}

function dumpRastro(itens) {
  return (itens || []).map((item) => {
    const ls = [`${item.n}. ${item.tabela}`];
    if (item.filtro) ls.push(`   WHERE ${item.filtro}`);
    if (!item.executado) ls.push(`   → não executado — ${item.detalhe}`);
    else if (String(item.detalhe || '').startsWith('ERRO:')) ls.push(`   → ${item.detalhe}`);
    else if (!item.linhas && (!item.detalhe || item.detalhe === '0 linhas')) ls.push('   → 0 linhas');
    else ls.push(`   → ${item.linhas} linha(s)${item.detalhe ? ' — ' + item.detalhe : ''}`);
    return ls.join('\n');
  }).join('\n\n');
}

linhas.push('', 'Rastro técnico');
linhas.push(`invoice_id=${invoiceId}${chave ? '  chave=' + chave : ''}`);
if (diag && Array.isArray(diag.rastro) && diag.rastro.length) {
  linhas.push('', dumpRastro(diag.rastro));
} else if (contigencia && contigencia.notificationId) {
  linhas.push(`contingência ${contigencia.notificationId}`);
}
if (entrega && Array.isArray(entrega.rastro) && entrega.rastro.length) {
  linhas.push('');
  linhas.push('Reconsulta POST /diagnostico/entrega');
  linhas.push(dumpRastro(entrega.rastro));
} else if (entrega && entrega.classificacaoEntrega) {
  linhas.push('');
  linhas.push(`Reconsulta POST /diagnostico/entrega → ${entrega.classificacaoEntrega}`);
}
if (xmlNoFtp === true) linhas.push('Rechecar SFTP → XML encontrado');
else if (xmlNoFtp === false) linhas.push('Rechecar SFTP → XML ainda ausente');
linhas.push(`execução n8n=${executionId}`);

const mensagem = linhas.join('\n');

return [{
  json: {
    referencia,
    numero: origem.numero,
    serie: origem.serie,
    invoiceId: invoiceId || null,
    encontrado: Boolean(origem.encontrado),
    motivo: origem.motivo,
    identificador: origem.identificador,
    executionId,
    proximaAcao,
    diagnostico,
    precisaAdmin,
    resolvido,
    assunto: `NF-e ${referencia} — ${assuntoSufixo}`,
    mensagem,
  },
}];

const run = $getWorkflowStaticData('run');
if (!Array.isArray(run.lote)) run.lote = [];
console.log(`▶ Invoice ausente no relatório ML  ${$json.referencia || ''}`);
const origem = $input.first().json;
const executionId = origem.executionId || $execution.id;
const mensagem =
  `NF ${origem.referencia || ''}\n\n` +
  '⚠️ Precisa de atenção — a nota não foi encontrada no relatório do Mercado Livre.\n\n' +
  'Sem o identificador da nota no Mercado Livre, o diagnóstico no Nerus não consegue rodar.\n\n' +
  'O que fazer:\n' +
  'Acionar o time técnico.\n\n' +
  `execução n8n=${executionId}`;

run.lote.push({
    referencia: origem.referencia,
    numero: origem.numero,
    serie: origem.serie,
    invoiceId: origem.invoiceId || null,
    encontrado: false,
    precisaAdmin: true,
    proximaAcao: 'nenhuma',
    diagnostico: 'A nota não foi encontrada no relatório do Mercado Livre.',
    mensagem,
    assunto: `NF-e ${origem.referencia} — não encontrada no ML`,
  });
return [{
  json: {
    referencia: origem.referencia,
    numero: origem.numero,
    serie: origem.serie,
    invoiceId: origem.invoiceId || null,
    encontrado: false,
    motivo: origem.motivo,
    identificador: origem.identificador,
    executionId,
    precisaAdmin: true,
    proximaAcao: 'nenhuma',
    assunto: `NF-e ${origem.referencia} — não encontrada no ML`,
    mensagem,
  },
}];

console.log(`▶ Guardar diagnóstico  ${$json.referencia || ''}  lote=${(($getWorkflowStaticData('run').lote || []).length) + 1}`);
const run = $getWorkflowStaticData('run');
if (!Array.isArray(run.lote)) run.lote = [];
const item = $input.first().json;
run.lote.push(item);
return $input.all();

const run = $getWorkflowStaticData('run');
const lote = Array.isArray(run.lote) ? run.lote : [];
const acoes = lote.map((d) => d.proximaAcao);
let espera = 'nenhuma';
if (acoes.includes('esperar_entrega')) espera = '10min';
else if (acoes.includes('contigencia')) espera = '2min';
console.log(`▶ Espera do lote  notas=${lote.length}  espera=${espera}`);
return [{ json: { espera, total: lote.length, executionId: $execution.id } }];

console.log(`▶ Montar relatórios do lote  ${($getWorkflowStaticData('run').lote || []).length}`);
const run = $getWorkflowStaticData('run');
const lote = Array.isArray(run.lote) ? run.lote : [];
const sftp = $input.first().json;
const executionId = $execution.id;
const originais = $('Montar resumo da checagem').first().json.notasAusentes || [];

function xmlNoFtpDe(numero, serie) {
  if (!sftp || !Array.isArray(sftp.notasAusentes)) return null;
  const ainda = sftp.notasAusentes.some(
    (n) => Number(n.numero) === Number(numero) && Number(n.serie) === Number(serie),
  );
  return !ainda;
}

function dumpRastro(itens) {
  return (itens || []).map((item) => {
    const ls = [`${item.n}. ${item.tabela}`];
    if (item.filtro) ls.push(`   WHERE ${item.filtro}`);
    if (!item.executado) ls.push(`   → não executado — ${item.detalhe}`);
    else if (String(item.detalhe || '').startsWith('ERRO:')) ls.push(`   → ${item.detalhe}`);
    else if (!item.linhas && (!item.detalhe || item.detalhe === '0 linhas')) ls.push('   → 0 linhas');
    else ls.push(`   → ${item.linhas} linha(s)${item.detalhe ? ' — ' + item.detalhe : ''}`);
    return ls.join('\n');
  }).join('\n\n');
}

function relatorioDe(diag) {
  const xmlNoFtp = xmlNoFtpDe(diag.numero, diag.serie);
  const referencia = diag.referencia || `${diag.numero}/${diag.serie}`;
  const invoiceId = diag.invoiceId || '';
  const chave = diag.chave || '';
  const diagnostico = diag.diagnostico || diag.mensagem || 'Não foi possível montar o diagnóstico.';
  const proximaAcao = diag.proximaAcao || 'nenhuma';
  const passos = Array.isArray(diag.passos) ? diag.passos : [];
  const contigencia = diag.contigencia;
  const c = passos.find((p) => p.id === 'contigencia');

  let oQueMonitorFez = 'Não reenviou o aviso: o problema não é falta de notificação do Mercado Livre.';
  if (c && c.status === 'ok') {
    if (xmlNoFtp === true) oQueMonitorFez = 'Reenviou o aviso ao sistema (contingência). Depois disso, o XML apareceu no FTP.';
    else if (xmlNoFtp === false) oQueMonitorFez = 'Reenviou o aviso ao sistema (contingência) e conferiu de novo. A nota ainda não chegou ao FTP.';
    else oQueMonitorFez = 'Reenviou o aviso ao sistema (contingência).';
  } else if (c && c.status === 'erro') {
    oQueMonitorFez = `Tentou reenviar o aviso ao sistema (contingência), mas não conseguiu: ${c.detalhe}`;
  } else if (proximaAcao === 'esperar_entrega') {
    oQueMonitorFez = xmlNoFtp === true
      ? 'Aguardou o envio ao FTP. O XML apareceu na pasta.'
      : 'Aguardou o envio ao FTP, mas o arquivo ainda não apareceu na pasta.';
  } else if (proximaAcao === 'rechecar_ftp') {
    oQueMonitorFez = xmlNoFtp === true
      ? 'Conferiu o FTP e encontrou o XML.'
      : 'O envio ao FTP já tinha sido disparado, mas o arquivo ainda não estava na pasta.';
  }

  let banner, oQueFazer, assuntoSufixo, resolvido, precisaAdmin;
  if (xmlNoFtp === true) {
    banner = '✅ Resolvido — o XML da nota já está no FTP.';
    oQueFazer = 'Nada a fazer.';
    assuntoSufixo = 'resolvido';
    resolvido = true;
    precisaAdmin = false;
  } else if (xmlNoFtp === false) {
    banner = '⚠️ Ainda não resolvido — a nota continua ausente no FTP.';
    oQueFazer = 'O monitor ainda vai conferir o lote de novo. Se persistir, acionar o time técnico.';
    assuntoSufixo = 'ainda ausente no FTP';
    resolvido = false;
    precisaAdmin = true;
  } else {
    banner = '⚠️ Precisa de atenção — a nota não chegou ao FTP.';
    oQueFazer = 'Acionar o time técnico.';
    assuntoSufixo = 'precisa de atenção';
    resolvido = false;
    precisaAdmin = true;
  }

  const linhas = [
    `NF ${referencia}`,
    '',
    banner,
    oQueFazer,
    '',
    xmlNoFtp === true ? 'O que tinha acontecido:' : 'O que aconteceu:',
    diagnostico,
    '',
    'O que o monitor fez:',
    oQueMonitorFez,
  ];
  if (xmlNoFtp !== true) {
    const pipeline = passos.filter((p) => p.id !== 'contigencia');
    const primeiroErro = pipeline.findIndex((p) => p.status === 'erro');
    const visiveis = primeiroErro >= 0 ? pipeline.slice(0, primeiroErro + 1) : pipeline;
    if (visiveis.length) {
      linhas.push('', 'Onde a integração parou:');
      for (const p of visiveis) {
        linhas.push(p.detalhe ? `• ${p.titulo} — ${p.detalhe}` : `• ${p.titulo}`);
      }
      if (primeiroErro >= 0 && primeiroErro < pipeline.length - 1) {
        linhas.push('Os passos seguintes ainda não rodaram por causa disso.');
      }
    }
  }
  linhas.push('', 'Rastro técnico');
  linhas.push(`invoice_id=${invoiceId}${chave ? '  chave=' + chave : ''}`);
  if (Array.isArray(diag.rastro) && diag.rastro.length) {
    linhas.push('', dumpRastro(diag.rastro));
  } else if (contigencia && contigencia.notificationId) {
    linhas.push(`contingência ${contigencia.notificationId}`);
  }
  if (xmlNoFtp === true) linhas.push('Rechecar SFTP → XML encontrado');
  else if (xmlNoFtp === false) linhas.push('Rechecar SFTP → XML ainda ausente');
  linhas.push(`execução n8n=${executionId}`);

  return {
    referencia,
    numero: diag.numero,
    serie: diag.serie,
    invoiceId: invoiceId || null,
    executionId,
    proximaAcao,
    diagnostico,
    precisaAdmin,
    resolvido,
    xmlNoFtp,
    assunto: `NF-e ${referencia} — ${assuntoSufixo}`,
    mensagem: linhas.join('\n'),
  };
}

